"""Public, inspectable prompt comparison. Original report and sample stay separate."""
import hashlib,html,json,shutil,zipfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];P=ROOT/'analysis-output/prompt-retune-debug-20261120';PAGE=ROOT/'website/runs/2026-11-20-3h';D=PAGE/'data'
s=json.loads((P/'summary.json').read_text(encoding='utf-8'));assert s['coverage']['unreviewed']==0
for src,dst in [('summary.json','prompt-summary.json'),('comparison.json','prompt-comparison.json'),('all-assessed-test-outputs.json','prompt-all-outputs.json')]:shutil.copy2(P/src,D/dst)
rows=[]
for phase in ['dev','heldout']:
 for name,r in s[phase]['profiles'].items():
  g=r['grades'];t=r['wall_ms']
  rows.append(f'<tr><td>{phase}</td><td>{name}</td><td>{r["count"]}</td><td>{g.get("good",0)} / {g.get("minor",0)} / {g.get("major",0)} / {g.get("unjudgeable",0)}</td><td>{t["median"]:.1f}</td><td>{t["p95"]:.1f}</td><td>{len(r["major_to_good"])+len(r["major_to_minor"])}</td><td>{len(r["introduced_major"])}</td></tr>')
archive=ROOT/'release-assets/debug-run-1795196244267574/prompt-test-evidence.zip'
with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED,compresslevel=5) as z:
 for phase in ['dev','heldout']:
  for name in ['manifest.json','warmup.json','loaded.json','gpu.jsonl','results.jsonl','COMPLETE.json','runner-frozen.py']:z.write(P/phase/name,phase+'/'+name)
 for folder in ['dev-review','heldout-review','full-audit']:
  for file in (P/folder).glob('*.json'):z.write(file,folder+'/'+file.name)
 for name in ['summary.json','comparison.json','all-assessed-test-outputs.json']:z.write(P/name,name)
 for name in ['study_run_prompt_20261120.py','full_audit_debug_20261120.py','assemble_full_audit_20261120.py','review_prompt_retune_20261120.py','review_heldout_20261120.py','summarize_prompt_retune_20261120.py']:z.write(ROOT/'tools'/name,'code/'+name)
 with_original=ROOT/'analysis-output/debug-run-1795196244267574/data/quality-full-review.json';z.write(with_original,'quality-full-review.json')
with zipfile.ZipFile(archive) as z:assert z.testzip() is None
sha=hashlib.sha256(archive.read_bytes()).hexdigest()
(D/'prompt-evidence-sha256.txt').write_text(sha+'  '+archive.name+'\n',encoding='ascii')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FrameLab — complete prompt comparison</title><link rel="stylesheet" href="report.css"><script src="prompt-test.js" defer></script></head><body><header><a class="brand" href="index.html">FRAME / LAB · AUDIT</a><button id="language">CZ / EN</button></header><main><h1 data-en="Every prompt result assessed." data-cs="Každý výstup promptu posouzený.">Every prompt result assessed.</h1><p data-en="3,768 test responses, zero unreviewed. The original 1,747 recorded translations are reviewed separately. Exact duplicate source/output pairs reuse an explicit assessment; every new output was read and assessed." data-cs="3 768 testovacích odpovědí, nehodnoceno 0. Původních 1 747 překladů ze záznamu je posouzených zvlášť. Přesně stejné dvojice vstup/výstup přebírají výslovné hodnocení; každý nový výstup byl přečten a posouzen.">3,768 test responses, zero unreviewed. The original 1,747 recorded translations are reviewed separately. Exact duplicate source/output pairs reuse an explicit assessment; every new output was read and assessed.</p><p data-en="The 300 development inputs informed the two candidate prompts. The frozen examples prompt then ran against the baseline on the remaining 1,284 pairs. These are fragments from the same recording, not an independent general-language benchmark. One AI reviewer; no verified human reference. Detailed notes are in Czech." data-cs="Podle 300 vývojových vstupů vznikly dvě úpravy promptu. Zmrazený prompt s příklady se pak porovnal s původním na zbývajících 1 284 dvojicích. Jsou to útržky ze stejného záznamu, nikoliv nezávislý obecný benchmark. Jeden AI hodnotitel, bez ověřené lidské reference. Podrobné poznámky jsou česky.">The 300 development inputs informed the two candidate prompts. The frozen examples prompt then ran against the baseline on the remaining 1,284 pairs. These are fragments from the same recording, not an independent general-language benchmark. One AI reviewer; no verified human reference. Detailed notes are in Czech.</p><div class="table-scroll"><table><thead><tr><th>Phase</th><th>Prompt</th><th>N</th><th>Good / minor / major / context</th><th>Median ms</th><th>P95 ms</th><th>Major → good/minor</th><th>New major</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><p data-en="Times measure warmed translation requests only, on an isolated Q5 runtime sharing the GPU with the unchanged app. OCR, reading hold and display are excluded. Background load was uncontrolled. Full prompts, model hash, settings, GPU samples, warmups and every output are downloadable. Changes of judgment caused by missing context are not counted as proven fixes." data-cs="Časy měří jen zahřáté požadavky překladu na izolovaném Q5 runtime, který sdílí GPU s nezměněnou aplikací. Nezahrnují OCR, ponechání předchozího titulku ani zobrazení. Zátěž na pozadí nebyla řízená. Ke stažení jsou celé prompty, hash modelu, nastavení, GPU vzorky, zahřívací vstupy a každý výstup. Přechod do nedostatku kontextu se nepočítá jako prokázaná oprava.">Times measure warmed translation requests only, on an isolated Q5 runtime sharing the GPU with the unchanged app. OCR, reading hold and display are excluded. Background load was uncontrolled. Full prompts, model hash, settings, GPU samples, warmups and every output are downloadable. Changes of judgment caused by missing context are not counted as proven fixes.</p><p data-en="Judgment corrections are disclosed in the original audit: #1186 is minor, #1577 is correct in context. The earlier 24-error sample remains archived unchanged; comparisons use the corrected, consistent labels. This is not model improvement." data-cs="Opravy hodnocení jsou popsané v původním auditu: #1186 je menší nepřesnost, #1577 je v kontextu správně. Starší vzorek s 24 chybami zůstává archivovaný beze změn; srovnání používá opravené a sjednocené známky. Nejde o zlepšení modelu.">Judgment corrections are disclosed in the original audit: #1186 is minor, #1577 is correct in context. The earlier 24-error sample remains archived unchanged; comparisons use the corrected, consistent labels. This is not model improvement.</p><div class="filters"><label>Search / hledání<input id="search" type="search" placeholder="#204 / shots"></label><label>Phase<select id="phase"><option value="all">All / vše</option><option>dev</option><option>heldout</option></select></label><label>Prompt<select id="profile"><option value="all">All / vše</option><option>examples-v1</option><option>rules-v1</option><option>baseline-repeat</option></select></label><label>Change / změna<select id="change"><option value="all">All / vše</option><option value="fixed">Major → good/minor</option><option value="regression">Good/minor → major</option><option value="changed">Different text / jiný text</option></select></label></div><p id="count" role="status"></p><div id="list"></div><div class="pagination"><button id="prev">←</button><span id="page"></span><button id="next">→</button></div><section class="downloads"><a href="data/prompt-summary.json">Summary JSON</a><a href="data/prompt-comparison.json">Every paired comparison JSON</a><a href="data/prompt-all-outputs.json">All 3,768 assessed outputs JSON</a><a href="data/prompt-test-evidence.zip">Prompts + raw results + GPU + grades ZIP</a><a href="data/prompt-evidence-sha256.txt">ZIP SHA-256</a></section><footer><a href="index.html#translations">All original 1,747 translations</a></footer></main></body></html>'''
decision='<aside class="notice"><p data-en="Decision: keep the production prompt. Examples reduced material errors from 21 to 17 on development, but increased them from 74 to 83 on validation: 11 fixed, 20 introduced. Median 396.0 → 401.8 ms. Added rules also worsened development quality. The app prompt was not changed." data-cs="Závěr: ponechat původní prompt. Příklady snížily podstatné chyby z 21 na 17 na vývojové sadě, ale v ověření je zvýšily ze 74 na 83: 11 oprav, 20 nových chyb. Medián 396,0 → 401,8 ms. Doplněná pravidla také zhoršila vývojovou sadu. Prompt aplikace se nezměnil.">Decision: keep the production prompt. Examples reduced material errors from 21 to 17 on development, but increased them from 74 to 83 on validation: 11 fixed, 20 introduced. Median 396.0 → 401.8 ms. Added rules also worsened development quality. The app prompt was not changed.</p></aside>'
page=page.replace('<div class="table-scroll">',decision+'<div class="table-scroll">',1)
(PAGE/'prompt-test.html').write_text(page,encoding='utf-8')
print(json.dumps(dict(outputs=s['coverage']['test_responses'],bytes=archive.stat().st_size,sha256=sha)))
